      const registry=await(await editorRequest('/api/asset/registry')).json(),records=new Map(registry.assets.map(a=>[a.path,a]));
      const graph=await referenceGraph(this.path,{read:async path=>{const record=records.get(path);if(!record)throw Error('에셋이 없어요: '+path);return record;},dependencyDepth:this.dependencyDepth,referencerDepth:this.referencerDepth,breadth:this.breadth,direction:this.direction});if(this.disposed||request!==this.request)return;
      const select=this.element.querySelector('[data-ref-type]');for(const kind of [...new Set(graph.nodes.map(n=>n.kind).filter(Boolean))].sort()){const option=document.createElement('option');option.value=kind;option.textContent=kind;select.append(option);}select.value=this.type;
      const nodes=graph.nodes,levels=[...new Set(nodes.map(n=>n.level))].sort((a,b)=>a-b),positions=new Map();let maxRows=1;for(const level of levels){const group=nodes.filter(n=>n.level===level);maxRows=Math.max(maxRows,group.length);group.forEach((n,i)=>positions.set(n.path,{x:levels.indexOf(level)*300+24,y:i*94+36}));}
      const width=Math.max(640,levels.length*300),height=Math.max(320,maxRows*94+72),host=this.element.querySelector('.reference-graph');
      const arrow='ref-arrow-'+crypto.randomUUID();host.innerHTML=`<div class="reference-graph-world" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}" aria-hidden="true"><defs><marker id="${arrow}" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" style="fill:#668ead;stroke:none"/></marker></defs>${graph.edges.filter(e=>positions.has(e.from)&&positions.has(e.to)).map(e=>{const a=positions.get(e.from),b=positions.get(e.to);return `<path marker-end="url(#${arrow})" d="M${a.x+236},${a.y+31} C${a.x+274},${a.y+31} ${b.x-38},${b.y+31} ${b.x},${b.y+31}"/>`;}).join('')}</svg>${nodes.map(n=>{const p=positions.get(n.path);return `<article style="left:${p.x}px;top:${p.y}px" class="reference-node ${n.path===this.path?'root':''} ${n.missing?'missing':''}"><button data-ref-root="${esc(n.path)}" ${n.missing?'disabled':''}>${icon(assetIcon(n.kind))}<strong>${esc(assetTitle(n.path))}</strong></button><small title="${esc(n.path)}">${esc(n.path)}</small><footer><span>${n.missing?'파일 없음':n.error?esc(n.error):((n.size||0)/1024).toFixed(1)+' KB'}${graph.truncated.includes(n.path)?' · 검색 제한':''}</span><button data-ref-open="${esc(n.path)}" ${n.missing?'disabled':''}>열기</button></footer></article>`;}).join('')}</div>`;
      this.graph=graph;for(const [i,n] of nodes.entries()){const el=host.querySelectorAll('.reference-node')[i];el.dataset.refPath=n.path;}this.applyFilters();this.setZoom(this.zoom);this.bindGraph(host);
