    this.element.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-ref-back'))this.navigateHistory(-1);else if(b.hasAttribute('data-ref-forward'))this.navigateHistory(1);else if(b.hasAttribute('data-ref-refresh'))this.render();else if(b.hasAttribute('data-ref-fit'))this.fit();else if(b.hasAttribute('data-ref-export'))this.export();else if(b.dataset.refRoot)this.navigate(b.dataset.refRoot);else if(b.dataset.refOpen){const n=this.graph.nodes.find(n=>n.path===b.dataset.refOpen);this.hooks.open({...n,name:n.path.split('/').pop()});}};
    this.element.onchange=e=>{if(e.target.hasAttribute('data-ref-type')){this.type=e.target.value;this.applyFilters();return;}if(e.target.hasAttribute('data-ref-depth'))this[e.target.dataset.refDepth]=Number(e.target.value);else if(e.target.hasAttribute('data-ref-breadth'))this.breadth=Number(e.target.value);else if(e.target.hasAttribute('data-ref-direction'))this.direction=e.target.value;else return;this.render();};
